#!/usr/bin/env python3
import sys
import json
import argparse
from pd.runtime import API

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--output", "-o",
        type=str, 
        default=None
    )
    args = parser.parse_args()

    api = API("/dev/puddleduck_ctrl")
    api.requestJointZeroRef("default");
    msg = api.waitFor(msg_type='joint_zero_ref', timeout=5)
    if msg is None:
        print("Timed out waiting for response", file=sys.stderr)
        sys.exit(1)

    payload = {
        "name": msg.name,
        "zero_ref":  list(msg.zero_ref),
        "low_range":  list(msg.low_range),
        "high_range":  list(msg.high_range)
    }
    if args.output is not None:
        with open(args.output, 'w') as f:
            json.dump(payload, f, indent=4)
    else:
        print(payload)
